#include <inttypes.h>
#include <stdio.h>
#include <string.h>

enum { MAX_PRINT_PARTS = 12 };

/**
 * @brief Collect single-use concatenation leaves in output order up to the
 * configured limit.
 *
 * @param block Instructions in the block containing the print.
 * @param before Index before which to search for a definition.
 * @param uses Use counts indexed by SSA value ID.
 * @param value Operand whose concatenation tree is being inspected.
 * @param[out] parts Buffer receiving the output operands.
 * @param[in,out] count Number of operands collected so far.
 * @return True if all leaves fit in the buffer.
 */
static bool collect_parts(const IrInstructionArray* block,
                          size_t before,
                          const size_t* uses,
                          IrOperand value,
                          IrOperand* parts,
                          size_t* count) {
  if (*count == MAX_PRINT_PARTS)
    return false;

  if (value.type == IR_OP_VALUE && uses[value.value.id] == 1)
    for (size_t i = before; i-- > 0;) {
      const IrInstruction* inst = &block->data[i];
      if (inst->result == value.value.id && inst->type == IR_INST_CONCAT)
        return collect_parts(block, i, uses, inst->operands.binary.left, parts,
                             count) &&
               collect_parts(block, i, uses, inst->operands.binary.right, parts,
                             count);
    }

  parts[(*count)++] = value;

  return true;
}

bool optimizer_stream_prints(Ctx* ctx, IrFunctionId fid) {
  IrFunction* fn = &ctx->ir.functions.data[fid];

  size_t* uses = ctx->optimizer.value_data;
  optimizer_count_value_uses(fn, uses);

  bool changed = false;
  for (IrBlockId b = 0; b < fn->blocks.count; b++) {
    IrInstructionArray* body = &fn->blocks.data[b].instructions;
    for (size_t i = body->count; i-- > 0;) {
      // AI generated by: Codex (GPT-6.2-sol)
      // Prompt: "Ok, implement all, remove things made redundant by this
      // change" Changes: Stream concatenations feeding the write operation.
      IrInstruction write = body->data[i];
      if (write.type != IR_INST_WRITE)
        continue;

      IrOperand parts[MAX_PRINT_PARTS];

      size_t count = 0;
      if (!collect_parts(body, i, uses, write.operands.unary.operand, parts,
                         &count) ||
          count < 2)
        continue;

      // A removed CONCAT costs at least 10. Each additional WRITE costs at
      // most 8.
      size_t original = body->count;

      for (size_t j = 0; j < count; j++) {
        write.operands.unary.operand = parts[j];
        ir_add_instruction(ctx, fid, b, write);
      }

      IrInstruction writes[MAX_PRINT_PARTS];

      memcpy(writes, body->data + original, count * sizeof(*writes));
      // Insert at the original print so effects from evaluating later parts
      // still happen before any of the replacement writes.
      ir_free_instruction(&body->data[i]);
      memmove(body->data + i + count, body->data + i + 1,
              (original - i - 1) * sizeof(*writes));
      memcpy(body->data + i, writes, count * sizeof(*writes));

      body->count--;
      changed = true;
    }
  }

  return changed;
}

