/**
 * @brief Get the exact target output bytes for an eligible literal write.
 *
 * @param inst Candidate write instruction.
 * @param number Buffer of at least 32 bytes for formatted integers.
 * @return Borrowed output text, or NULL if the output is not known here.
 */
static const char* literal_output(const IrInstruction* inst, char* number) {
  if (inst->type != IR_INST_WRITE)
    return NULL;

  IrOperand value = inst->operands.unary.operand;
  switch (value.type) {
    case IR_OP_STRING:
      return value.value.string_value;

    case IR_OP_INT32:
      snprintf(number, 32, "%" PRId64, value.value.int32_value);
      return number;

    case IR_OP_BOOL:
      return value.value.bool_value ? "true" : "false";

    case IR_OP_UNIT:
      return "()";

    default:
      return NULL;
  }
}

void optimizer_group_literal_prints(Ctx* ctx, IrFunctionId fid) {
  IrFunction* fn = &ctx->ir.functions.data[fid];
  for (IrBlockId b = 0; b < fn->blocks.count; b++) {
    IrInstructionArray* body = &fn->blocks.data[b].instructions;
    for (size_t start = 0; start < body->count; start++) {
      char number[32];
      size_t end = start;
      size_t length = 0;

      for (; end < body->count; end++) {
        const char* text = literal_output(&body->data[end], number);

        // Keep effects and dynamic output in their original positions.
        if (!text)
          break;

        length += strlen(text);
      }

      if (end - start < 2)
        continue;

      // Allocate the combined string before freeing any of its source operands.
      char* text = TRY_MALLOC(length + 1);
      char* dest = text;

      for (size_t i = start; i < end; i++) {
        const char* part = literal_output(&body->data[i], number);
        size_t size = strlen(part);
        memcpy(dest, part, size);
        dest += size;
        ir_free_instruction(&body->data[i]);
      }

      *dest = '\0';
      body->data[start] = (IrInstruction){
          .type = IR_INST_WRITE,
          .result = IR_INVALID_ID,
          .result_type = IR_UNIT,
          .operands.unary.operand = {IR_OP_STRING, {.string_value = text}},
      };
      memmove(body->data + start + 1, body->data + end,
              (body->count - end) * sizeof(*body->data));
      body->count -= end - start - 1;
    }
  }
}
